import React, { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import {
  FiArrowLeft,
  FiPlus,
  //FiRefreshCw
} from "react-icons/fi";

import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import DataTable from "../../components/DataTable";
import Loading from "../../components/Loading";

import { studentApi } from "../../api/studentApi";
import { gradeApi } from "../../api/gradeApi";

import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";

import {
  fullName,
  gpaRemark
} from "../../utils/formatters";


export default function StudentGrades() {
  const { id } = useParams();
  const navigate = useNavigate();
  const toast = useToast();


  // =========================================================
  // STATE
  // =========================================================

  const [student, setStudent] = useState(null);

  const [grades, setGrades] = useState([]);

  const [gpa, setGpa] = useState(null);

  const [isLoading, setIsLoading] = useState(true);

  const [error, setError] = useState("");


  // =========================================================
  // LOAD STUDENT + GRADES + GPA
  // =========================================================

  useEffect(() => {
    let mounted = true;


    async function loadStudentGrades() {
      setIsLoading(true);
      setError("");


      try {
        const [
          studentResponse,
          gradesResponse,
          gpaResponse
        ] = await Promise.all([
          studentApi.getOne(id),
          gradeApi.getByStudent(id),
          gradeApi.getGpa(id)
        ]);


        if (!mounted) {
          return;
        }


        // ===================================================
        // STUDENT
        // ===================================================

        const studentData =
          studentResponse?.data;


        /*
         * Backend getStudent returns:
         *
         * {
         *   success: true,
         *   student: {...}
         * }
         *
         * So use .student first.
         */

        const studentObject =
          studentData?.student ??
          studentData?.data ??
          studentData;


        if (
          !studentObject ||
          typeof studentObject !== "object"
        ) {
          throw new Error(
            "Student information could not be loaded."
          );
        }


        setStudent(studentObject);


        // ===================================================
        // GRADES
        // ===================================================

        const gradesData =
          gradesResponse?.data;


        /*
         * Backend returns:
         *
         * {
         *   success: true,
         *   student: {...},
         *   total_courses: 2,
         *   grades: [...]
         * }
         *
         * IMPORTANT:
         * The grades are inside .grades
         */

        let gradeList = [];


        if (
          Array.isArray(
            gradesData?.grades
          )
        ) {

          gradeList =
            gradesData.grades;

        } else if (
          Array.isArray(
            gradesData?.data
          )
        ) {

          gradeList =
            gradesData.data;

        } else if (
          Array.isArray(gradesData)
        ) {

          gradeList =
            gradesData;

        }


        setGrades(gradeList);


        // ===================================================
        // GPA
        // ===================================================

        const gpaData =
          gpaResponse?.data;


        /*
         * Backend returns:
         *
         * {
         *   success: true,
         *   student: {...},
         *   total_courses: 2,
         *   total_credit_hours: 6,
         *   total_quality_points: 20.1,
         *   gpa: 3.35,
         *   courses: [...]
         * }
         */


        const gpaObject =
          gpaData?.data ??
          gpaData;


        if (
          gpaObject &&
          typeof gpaObject === "object"
        ) {
          setGpa(gpaObject);
        } else {
          setGpa(null);
        }


      } catch (err) {

        console.error(
          "Failed to load student grades:",
          err
        );


        if (!mounted) {
          return;
        }


        const message =
          extractErrorMessage(
            err,
            "Unable to load student grades."
          );


        setError(message);


        toast.error(message);

      } finally {

        if (mounted) {
          setIsLoading(false);
        }

      }
    }


    if (id) {
      loadStudentGrades();
    }


    return () => {
      mounted = false;
    };

  }, [id, toast]);


  // =========================================================
  // TABLE COLUMNS
  // =========================================================

  const columns = [

    {
      key: "course_code",

      label: "Course Code",

      render: (row) => (

        <span
          className="
            font-mono
            text-xs
            bg-navy-50
            text-navy-700
            px-2
            py-1
            rounded
          "
        >
          {row.course_code ||
            row.course?.course_code ||
            row.course?.code ||
            "—"}
        </span>

      )
    },


    {
      key: "course_name",

      label: "Course Name",

      render: (row) => (

        <span>
          {row.course_name ||
            row.course?.course_name ||
            row.course?.name ||
            "—"}
        </span>

      )
    },


    {
      key: "credit_hour",

      label: "Credit Hour",

      hideOnMobile: true,

      render: (row) => (

        <span>
          {row.credit_hour ??
            row.course?.credit_hour ??
            "—"}
        </span>

      )
    },


    {
      key: "semester",

      label: "Semester",

      hideOnMobile: true,

      render: (row) => (

        <span>
          {row.semester || "—"}
        </span>

      )
    },


    {
      key: "academic_year",

      label: "Academic Year",

      hideOnMobile: true,

      render: (row) => (

        <span>
          {row.academic_year || "—"}
        </span>

      )
    },


    {
      key: "grade",

      label: "Grade",

      render: (row) => (

        <span
          className="
            font-mono
            text-sm
            font-semibold
            text-navy-800
            bg-navy-50
            px-2.5
            py-1
            rounded
          "
        >
          {row.grade || "—"}
        </span>

      )
    },


    {
      key: "remark",

      label: "Remark",

      hideOnMobile: true,

      render: (row) => (

        <span>
          {row.remark || "—"}
        </span>

      )
    }

  ];


  // =========================================================
  // GPA VALUE
  // =========================================================

  const gpaValue =
    gpa?.gpa ??
    gpa?.value ??
    null;


  // =========================================================
  // LOADING
  // =========================================================

  if (isLoading) {

    return (

      <DashboardLayout>

        <Loading
          label="Loading grade report..."
        />

      </DashboardLayout>

    );

  }


  // =========================================================
  // PAGE
  // =========================================================

  return (

    <DashboardLayout>

      {/* =====================================================
          BACK BUTTON
      ====================================================== */}

      <Link
        to="/grades"
        className="
          inline-flex
          items-center
          gap-1.5
          text-sm
          text-navy-600
          hover:text-navy-800
          mb-4
        "
      >

        <FiArrowLeft size={14} />

        Back to Student Search

      </Link>


      {/* =====================================================
          ERROR
      ====================================================== */}

      {error && (

        <div
          className="
            mb-5
            rounded-lg
            border
            border-red-200
            bg-red-50
            px-4
            py-3
            text-sm
            text-red-700
          "
        >

          {error}

        </div>

      )}


      {/* =====================================================
          MAIN GRID
      ====================================================== */}

      <div
        className="
          grid
          lg:grid-cols-3
          gap-5
        "
      >


        {/* ===================================================
            STUDENT / GPA CARD
        ==================================================== */}

        <Card
          className="
            p-6
            lg:col-span-1
            h-fit
          "
        >

          <p
            className="
              text-xs
              uppercase
              tracking-wide
              text-muted
              mb-1
            "
          >
            Student
          </p>


          <h1
            className="
              font-display
              text-lg
              text-navy-800
              mb-1
            "
          >

            {student
              ? fullName(student)
              : "—"}

          </h1>


          <p
            className="
              font-mono
              text-xs
              text-navy-600
              mb-6
            "
          >

            {student?.registration_number ||
              "—"}

          </p>


          {/* =================================================
              GPA
          ================================================== */}

          {gpaValue === null ||
          gpaValue === undefined ? (

            <div
              className="
                text-center
                py-8
                text-sm
                text-muted
              "
            >

              GPA not available yet.

            </div>

          ) : (

            <div
              className="
                flex
                flex-col
                items-center
              "
            >

              {/* GPA CIRCLE */}

              <div
                className="
                  relative
                  h-36
                  w-36
                  flex
                  items-center
                  justify-center
                "
              >

                <svg
                  viewBox="0 0 120 120"
                  className="
                    h-36
                    w-36
                    -rotate-90
                  "
                >

                  {/* Background circle */}

                  <circle
                    cx="60"
                    cy="60"
                    r="52"
                    fill="none"
                    stroke="#E3E7EF"
                    strokeWidth="10"
                  />


                  {/* GPA progress */}

                  <circle
                    cx="60"
                    cy="60"
                    r="52"
                    fill="none"
                    stroke="#C89B3C"
                    strokeWidth="10"
                    strokeLinecap="round"
                    strokeDasharray={`
                      ${(Math.min(
                        Number(gpaValue),
                        4
                      ) / 4) * 326.7}
                      326.7
                    `}
                  />

                </svg>


                {/* GPA TEXT */}

                <div
                  className="
                    absolute
                    text-center
                  "
                >

                  <p
                    className="
                      text-[11px]
                      text-muted
                      uppercase
                      tracking-wide
                    "
                  >
                    Current GPA
                  </p>


                  <p
                    className="
                      font-mono
                      text-3xl
                      text-navy-800
                      mt-0.5
                    "
                  >

                    {Number(
                      gpaValue
                    ).toFixed(2)}

                  </p>


                  <p
                    className="
                      text-xs
                      text-gold-600
                      font-medium
                      mt-0.5
                    "
                  >

                    {gpaRemark(gpaValue)}

                  </p>

                </div>

              </div>


              {/* =================================================
                  GPA DETAILS
              ================================================== */}

              <div
                className="
                  grid
                  grid-cols-2
                  gap-3
                  mt-5
                  w-full
                  text-center
                "
              >

                {/* CREDIT HOURS */}

                <div
                  className="
                    bg-paper
                    rounded-lg
                    py-3
                  "
                >

                  <p
                    className="
                      font-mono
                      text-base
                      text-navy-800
                    "
                  >

                    {gpa?.total_credit_hours ??
                      gpa?.credit_hours ??
                      "0"}

                  </p>


                  <p
                    className="
                      text-[11px]
                      text-muted
                      mt-1
                    "
                  >
                    Total Credit Hours
                  </p>

                </div>


                {/* QUALITY POINTS */}

                <div
                  className="
                    bg-paper
                    rounded-lg
                    py-3
                  "
                >

                  <p
                    className="
                      font-mono
                      text-base
                      text-navy-800
                    "
                  >

                    {gpa?.total_quality_points ??
                      gpa?.quality_points ??
                      "0"}

                  </p>


                  <p
                    className="
                      text-[11px]
                      text-muted
                      mt-1
                    "
                  >
                    Quality Points
                  </p>

                </div>

              </div>

            </div>

          )}

        </Card>


        {/* ===================================================
            GRADES TABLE
        ==================================================== */}

        <Card
          className="
            lg:col-span-2
          "
        >

          {/* TABLE HEADER */}

          <div
            className="
              flex
              items-center
              justify-between
              p-5
              border-b
              border-line
            "
          >

            <div>

              <p
                className="
                  font-display
                  text-base
                  text-navy-800
                "
              >
                Course Grades
              </p>


              <p
                className="
                  text-xs
                  text-muted
                  mt-1
                "
              >

                {grades.length}{" "}
                {grades.length === 1
                  ? "course"
                  : "courses"}

              </p>

            </div>


            <Link
              to="/grades/assign"
              className="
                flex
                items-center
                gap-1.5
                text-xs
                font-medium
                bg-navy-700
                text-white
                px-3
                py-1.5
                rounded-lg
                hover:bg-navy-800
                transition
              "
            >

              <FiPlus size={13} />

              Assign Grade

            </Link>

          </div>


          {/* DATA TABLE */}

          <DataTable

            columns={columns}

            rows={grades}

            isLoading={false}

            error={error}

            emptyTitle={
              "No grades available for this student."
            }

            emptyDescription={
              "Assign a grade for a registered course to see it here."
            }

            emptyAction={{
              label: "Assign Grade",

              onClick: () =>
                navigate("/grades/assign")
            }}

          />

        </Card>

      </div>

    </DashboardLayout>

  );
}
